const DIVISION_LABEL_BY_ID = Object.fromEntries(ENGLISH_PYRAMID_DIVISIONS.map((d) => [d.id, d.label]));

function draftBandOf(meta: EnglishPyramidTeamMeta): EnglishPyramidDraftBand {
  return meta.draftBand ?? 'title';
}

/** Division used for draft bands / fairness ranks (may differ after promotion). */
export function getDraftDivisionId(code: string): string | null {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[code];
  if (!meta) return null;
  return meta.draftDivisionId ?? meta.divisionId;
}

/** Division the club plays in this season (fixtures / live scores). */
export function getPlayingDivisionId(code: string): string | null {
  return ENGLISH_PYRAMID_TEAM_BY_CODE[code]?.divisionId ?? null;
}

function buildPreSeasonOddsRankByCode(): Record<string, number> {
  const byDivisionBand = new Map<string, EnglishPyramidTeamMeta[]>();
  for (const meta of Object.values(ENGLISH_PYRAMID_TEAM_BY_CODE)) {
    const draftDiv = meta.draftDivisionId ?? meta.divisionId;
    const key = `${draftDiv}:${draftBandOf(meta)}`;
    const list = byDivisionBand.get(key) ?? [];
    list.push(meta);
    byDivisionBand.set(key, list);
  }

  const ranks: Record<string, number> = {};
  for (const [key, teams] of byDivisionBand) {
    const band = key.split(':')[1] as EnglishPyramidDraftBand;
    teams
      .sort((a, b) => {
        if (band === 'survival') {
          const aRel = a.relegationOddsDecimal ?? a.outrightOddsDecimal;
          const bRel = b.relegationOddsDecimal ?? b.outrightOddsDecimal;
          return aRel - bRel || a.code.localeCompare(b.code);
        }
        return (
          a.outrightOddsDecimal - b.outrightOddsDecimal || a.code.localeCompare(b.code)
        );
      })
      .forEach((team, index) => {
        ranks[team.code] = index + 1;
      });
  }
  return ranks;
}

const PRESEASON_ODDS_RANK_BY_CODE = buildPreSeasonOddsRankByCode();

export function getPreSeasonOddsRank(code: string): number | null {
  return PRESEASON_ODDS_RANK_BY_CODE[code] ?? null;
}

export function getDraftBand(code: string): EnglishPyramidDraftBand | null {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[code];
  return meta ? draftBandOf(meta) : null;
}

export function teamCodeMatches(matchTla: string, playerTeamCode: string): boolean {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[playerTeamCode];
  const normalized = matchTla.trim().toUpperCase();
  if (playerTeamCode.toUpperCase() === normalized) return true;
  return (meta?.searchNames ?? []).some((name) => name.toUpperCase() === normalized);
}

export function getEnglishPyramidTeamSearchTerms(code: string): string[] {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[code];
  if (!meta) return [code];
  return [...new Set([meta.code, meta.name, ...(meta.searchNames ?? [])])];
}

/** Clubs in each division for 2026/27 — maps survival R#k to a table place (R#1 → last). */
export const ENGLISH_PYRAMID_DIVISION_CLUB_COUNT: Readonly<Record<string, number>> = {
  PL: 20,
  CH: 24,
  L1: 24,
  L2: 24,
  NL: 24,
  NLN: 24,
  NLS: 24,
};

function toOrdinal(n: number): string {
  const mod100 = n % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${n}th`;
  switch (n % 10) {
    case 1:
      return `${n}st`;
    case 2:
      return `${n}nd`;
    case 3:
      return `${n}rd`;
    default:
      return `${n}th`;
  }
}

/**
 * Pre-season predicted table place from draft odds.
 * Title #1 → 1st; survival R#1 (relegation favourite) → last (20th in PL, 24th elsewhere).
 */
export function getPreSeasonTablePlace(code: string): number | null {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[code];
  if (!meta) return null;
  const rank = PRESEASON_ODDS_RANK_BY_CODE[code];
  if (rank == null) return null;
  const draftDiv = meta.draftDivisionId ?? meta.divisionId;
  const size = ENGLISH_PYRAMID_DIVISION_CLUB_COUNT[draftDiv];
  if (!size) return null;
  if (draftBandOf(meta) === 'survival') {
    return size - rank + 1;
  }
  return rank;
}

export function formatPreSeasonTablePlace(code: string): string | null {
  const place = getPreSeasonTablePlace(code);
  return place != null ? toOrdinal(place) : null;
}

export function formatTeamLabel(code: string): string {
  const meta = ENGLISH_PYRAMID_TEAM_BY_CODE[code];
  if (!meta) return code;
  const draftDiv = meta.draftDivisionId ?? meta.divisionId;
  const draftLabel = DIVISION_LABEL_BY_ID[draftDiv];
  const playingLabel = DIVISION_LABEL_BY_ID[meta.divisionId];
  const place = formatPreSeasonTablePlace(code);
  const promoted = Boolean(meta.draftDivisionId && meta.draftDivisionId !== meta.divisionId);
  const divisionNote =
    promoted && draftLabel && playingLabel
      ? `${draftLabel} → ${playingLabel}`
      : draftLabel;
  if (place && divisionNote) {
    return `${meta.name} (${place}, ${divisionNote})`;
  }
  if (place) return `${meta.name} (${place})`;
  return divisionNote ? `${meta.name} (${divisionNote})` : meta.name;
}

/** Squad table / chip label — club name with pre-season place, e.g. Arsenal (1st), Hull (20th). */
export function formatTeamNameShort(code: string): string {
  return ENGLISH_PYRAMID_TEAM_BY_CODE[code]?.name ?? code;
}

/** Club name with start-of-season ranking in brackets for squad summaries. */
export function formatTeamNameWithSeed(code: string): string {
  const name = formatTeamNameShort(code);
  const place = formatPreSeasonTablePlace(code);
  return place ? `${name} (${place})` : name;
}

const DRAFT_DIVISION_ORDER = Object.fromEntries(
  ENGLISH_PYRAMID_DIVISIONS.map((division, index) => [division.id, index])
);

/** Sort squad codes by draft division (PL→NLS), title pick before survival within each rung. */
export function compareTeamCodesByDraftDivision(a: string, b: string): number {
  const divA = getDraftDivisionId(a) ?? '';
  const divB = getDraftDivisionId(b) ?? '';
  const orderCmp = (DRAFT_DIVISION_ORDER[divA] ?? 99) - (DRAFT_DIVISION_ORDER[divB] ?? 99);
  if (orderCmp !== 0) return orderCmp;
  const bandA = getDraftBand(a) === 'survival' ? 1 : 0;
  const bandB = getDraftBand(b) === 'survival' ? 1 : 0;
  return bandA - bandB;
}

export function sortTeamCodesByDraftDivision(codes: readonly string[]): string[] {
  return [...codes].sort(compareTeamCodesByDraftDivision);
}

